// src/report/render.ts
function safeJson(value) {
  return JSON.stringify(value).replace(/</g, "\\u003c").replace(/\u2028/g, "\\u2028").replace(/\u2029/g, "\\u2029");
}
function renderReport(data) {
  const marker = "__REPORT_DATA__";
  const at = report_default.indexOf(marker);
  if (at < 0) throw new Error("template do relatório sem marcador de dados");
  return report_default.slice(0, at) + safeJson(data) + report_default.slice(at + marker.length);
}

